/// <summary>
/// PaffH 07.11.25
/// </summary>
/// <param name = "_sections">List</param>
/// <returns>List</returns>
[DataMember("sections"),
    AifCollectionType('_sections', Types::Class, classStr(NDXBVEmailRequestAIDBSectionContract))]
public List parmSections(List _sections = sections)
{
    sections = _sections;
    return sections;
}

/// <summary>
/// PaffH 07.11.25
/// last modified: PaffH 05.12.25
/// </summary>
protected void new()
{
    sections = new List(Types::Class);
    sections.addEnd(NDXBVEmailRequestAIDBSectionADAContract::construct());
    sections.addEnd(NDXBVEmailRequestAIDBSectionBuildingOwnerContract::construct());
    sections.addEnd(NDXBVEmailRequestAIDBSectionContactPersonContract::construct());
    sections.addEnd(NDXBVEmailRequestAIDBSectionHeaderAIDBDocumentContract::construct());
    sections.addEnd(NDXBVEmailRequestAIDBSectionInstallerContract::construct());
    sections.addEnd(NDXBVEmailRequestAIDBSectionLineItemContract::construct());
    sections.addEnd(NDXBVEmailRequestAIDBSectionOrganisationContract::construct());
    sections.addEnd(NDXBVEmailRequestAIDBSectionPlanerContract::construct());
    sections.addEnd(NDXBVEmailRequestAIDBSectionProjectContract::construct());
    sections.addEnd(NDXBVEmailRequestAIDBSectionRequestContract::construct());
    sections.addEnd(NDXBVEmailRequestAIDBSectionDemandContract::construct());
    sections.addEnd(NDXBVEmailRequestAIDBSectionEmailContract::construct());
}

/// <summary>
/// PaffH 07.11.25
/// </summary>
/// <returns>NDXBVEmailRequestAIDBContract</returns>
public static NDXBVEmailRequestAIDBContract construct()
{
    NDXBVEmailRequestAIDBContract contract = new NDXBVEmailRequestAIDBContract();
    return contract;
