/// <summary>
/// PaffH 07.11.25
/// </summary>
/// <param name = "_formHandler">NDXBVEMailRequestControlCenterAIDBForm</param>
/// <param name = "_sectionType">NDXBVEmailRequestSectionType</param>
public void populate(NDXBVEMailRequestControlCenterAIDBForm _formHandler, NDXBVEmailRequestSectionType _sectionType)
{
    NDXBVEmailRequestAIDBSectionContract sectionContract;
    ListEnumerator enum = sections.getEnumerator();
    while (enum.moveNext())
    {
        sectionContract = enum.current();
        if (sectionContract.parmSectionType() == _sectionType)
        {
            sectionContract.populate(_formHandler);
        }
    }
}

/// <summary>
/// PaffH 13.11.25
/// </summary>
/// <param name = "_formHandler">NDXBVEMailRequestControlCenterAIDBForm</param>
public void populateAll(NDXBVEMailRequestControlCenterAIDBForm _formHandler)
{
    NDXBVEmailRequestAIDBSectionContract sectionContract;
    ListEnumerator enum = sections.getEnumerator();
    while (enum.moveNext())
    {
        sectionContract = enum.current();
        this.populate(_formHandler, sectionContract.parmSectionType());
    }
}

/// <summary>
/// PaffH 13.11.25
/// </summary>
/// <returns>List</returns>
public List findAllFieldValuesAsString()
{
    List list = new List(Types::String);

    NDXBVEmailRequestAIDBSectionContract sectionContract;
    NDXBVEmailRequestAIDBSectionGroupContract sectionGroupContract;
    ListEnumerator enumSection = sections.getEnumerator();
    while (enumSection.moveNext())
    {
        sectionContract = enumSection.current();
        ListEnumerator enumSectionGroup = sectionContract.parmSectionGroups().getEnumerator();
        while (enumSectionGroup.moveNext())
        {
            sectionGroupContract = enumSectionGroup.current();
            list.addEnd(sectionGroupContract.parmAiField().parmFieldValueAsStr());
        }
    }
    return list;
}
